Sys.setlocale('LC_CTYPE','English_United States.utf8');setwd(Sys.getenv("REVISION_ROOT", unset = "work/reproduction"))
s<-readRDS('spatial/all_spot_scores.rds');man<-read.csv('tables/S07_spatial_section_manifest.csv');if(!file.exists('spatial/fixed_denominator_applied.txt')){for(nm in man$sample){i<-s$sample==nm;k<-man$panel_genes_detected[man$sample==nm];s$panel14[i]<-s$panel14[i]*k/14;s$panel13_no_DSE[i]<-s$panel13_no_DSE[i]*(k-1)/13};saveRDS(s,'spatial/all_spot_scores.rds');write.csv(s,gzfile('spatial/all_spot_scores.csv.gz','wt'),row.names=FALSE);writeLines('Fixed panel denominator 14 or 13; absent genes contribute zero. This positive constant within each section leaves standardized GLS, Pearson, and Moran statistics invariant.','spatial/fixed_denominator_applied.txt')}
r<-aggregate(s[,c('panel14','panel13_no_DSE','genetic_core4')],s[,c('sample','donor','condition','areas')],mean);names(r)[4]<-'area';nn<-aggregate(rep(1,nrow(s)),s[,c('sample','areas')],sum);r$n_spots<-nn$x[match(paste(r$sample,r$area),paste(nn$sample,nn$areas))];write.csv(r,'tables/S09_all_section_region_scores.csv',row.names=FALSE)
d<-aggregate(r[,c('panel14','panel13_no_DSE','genetic_core4')],r[,c('donor','condition','area')],mean);write.csv(d,'tables/S09_donor_region_scores.csv',row.names=FALSE);rs<-list();for(mod in c('panel14','panel13_no_DSE','genetic_core4'))for(ref in c('LC','PPWM')){a<-d[d$condition=='MS' & d$area=='LR',c('donor',mod)];b<-d[d$condition=='MS' & d$area==ref,c('donor',mod)];v<-merge(a,b,by='donor');dif<-v[[2]]-v[[3]];ww<-wilcox.test(dif,mu=0,exact=FALSE);rs[[length(rs)+1]]<-data.frame(module=mod,contrast=paste0('LR_minus_',ref),n_donors=nrow(v),mean_difference=mean(dif),median_difference=median(dif),P=ww$p.value)};rs<-do.call(rbind,rs);rs$q_BH<-p.adjust(rs$P,'BH');write.csv(rs,'tables/S09_donor_paired_region_tests.csv',row.names=FALSE);print(rs)
